package com.moviebooking.notification.exception;
import com.moviebooking.notification.dto.ApiResponse;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.bind.MethodArgumentNotValidException;
@RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler(NotificationNotFoundException.class) ResponseEntity<ApiResponse<Void>> missing(NotificationNotFoundException e){return ResponseEntity.status(HttpStatus.NOT_FOUND).body(ApiResponse.error("Notification not found","NOTIFICATION_NOT_FOUND"));}@ExceptionHandler({InvalidNotificationEventException.class,MethodArgumentNotValidException.class}) ResponseEntity<ApiResponse<Void>> invalid(Exception e){return ResponseEntity.badRequest().body(ApiResponse.error(e.getMessage(),"INVALID_NOTIFICATION_EVENT"));}@ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Void>> general(Exception e){return ResponseEntity.status(500).body(ApiResponse.error("An unexpected error occurred","INTERNAL_ERROR"));}}
